namespace BlockLogger.WebDashboard;

internal static class WebDashboardPolishScript
{
    public const string RetentionHtml = """
<div class="card perfSection"><div class="cardHeader"><h3>Module Retention &amp; Queues</h3></div>
<p class="small">Compare Suite-owned queues and caches alongside heap readings. Refresh and export are manual; no heap walk or forced collection runs.</p>
<div class="toolbar"><button id="retentionRefresh">Refresh Counters</button><button id="retentionExport" disabled>Download Diagnostics</button><span id="retentionState" role="status" aria-live="polite">Not captured</span></div>
<div id="retentionCounters" class="grid"></div><div id="retentionComparison" class="small"></div><details><summary>WebPanel cache lifetimes</summary><div id="retentionKeys" class="tableWrap"></div></details></div>
""";
    public const string InvestigationHtml = """
<div class="card perfSection"><div class="cardHeader"><h3>Investigation Overview</h3></div>
<p class="small">Combine restrictions, anti-cheat evidence, effective role policies and snapshot headers. Inventory contents and block history load on demand.</p>
<div class="toolbar"><button id="investigationLoad">Load Investigation</button><button id="investigationBlocks">Load Block History</button><button id="investigationExport" disabled>Download Investigation</button><span id="investigationState" role="status" aria-live="polite">Choose a player</span></div>
<div id="investigationBody"></div><div id="investigationBlockRows" class="tableWrap"></div></div>
""";
    public const string Script = """
let retentionData=null,retentionPrevious=null,retentionBusy=false;
let investigationData=null,investigationGeneration=0,investigationBusy=false,investigationBlocksBusy=false;
let roleBatchDraft=null,rolePolishGeneration=0;
function polishDownload(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function polishMetric(label,value,note=''){return `<div class="card"><div class="metricLabel">${esc(label)}</div><div class="metricValue" style="font-size:20px">${esc(value)}</div><div class="small">${esc(note)}</div></div>`;}
function policyPreviewMarkup(d){if(!d)return '<p class="small">Policies unavailable.</p>';return `<p><b>${esc(d.name||d.code||'Role')}</b> · Home limit ${Number(d.homeLimit??0)} (${esc(d.homeSource||'')}) · ${Number(d.claimAllowance||0)} claim blocks / ${Number(d.claimAreas||0)} areas</p><div class="tableWrap"><table><thead><tr><th>Command</th><th>Access</th><th>Cooldown</th><th>Source</th></tr></thead><tbody>${(d.commands||[]).map(c=>`<tr><td>/${esc(c.command)}</td><td>${c.allowed?'Allowed':'Denied'}</td><td>${Number(c.cooldownSeconds||0)}s</td><td>${esc(c.source)}</td></tr>`).join('')}</tbody></table></div><details><summary>${(d.privileges||[]).length} effective privileges</summary><p class="small">${esc((d.privileges||[]).join(', ')||'None')}</p><p class="small">Direct denials: ${esc((d.deniedPrivileges||[]).join(', ')||'None')}</p></details><p class="small">${esc(d.note||'')}</p>`;}
async function loadRetentionCounters(){if(retentionBusy)return;retentionBusy=true;$('retentionRefresh').disabled=true;$('retentionState').textContent='Capturing counters…';try{const d=await api('/api/operations/diagnostics');retentionPrevious=retentionData;retentionData=d;const w=d.webPanel||{},a=d.admin||{},c=d.antiCheat||{},l=d.logger||{},o=d.oreShield||{};$('retentionCounters').innerHTML=[polishMetric('Panel cache entries',`${w.entries??0} / ${w.capacity??128}`,`${w.pending??0} refreshes pending`),polishMetric('Panel cleanup',`${w.evictions??0} evictions`,`${w.clears??0} clears · ${w.failures??0} failed refreshes`),polishMetric('Logger queue',Number(l.pendingEvents||0)+Number(l.pendingSnapshots||0),`${l.droppedEvents??0} dropped events`),polishMetric('Inventory history',a.snapshotHeaders??0,`${a.loadedPayloads??0} payloads in memory`),polishMetric('Sampled item bytes',`${(Number(a.sampledBytes||0)/1048576).toFixed(2)} MiB`,a.sampleMayBeTruncated?'Sample limit reached':'Item payload bytes; excludes object overhead'),polishMetric('Mod DB cache',`${(Number(c.modDbEstimatedBytes||0)/1048576).toFixed(1)} MiB`,`${c.modDbEntries??0} entries · ${c.pendingVerifications??0} pending`),polishMetric('OreShield reveal jobs',o.pendingVeinJobs??0,`Oldest ${Number(o.oldestVeinJobAgeMs||0)} ms`)].join('');$('retentionKeys').innerHTML=`<table><thead><tr><th>Cache</th><th>Age</th><th>State</th></tr></thead><tbody>${(w.keys||[]).map(k=>`<tr><td>${esc(k.key)}</td><td>${k.ageMs==null?'Not captured':`${Number(k.ageMs)} ms`}</td><td>${k.pending?'Refreshing':k.stale?'Invalidated':'Cached'}</td></tr>`).join('')}</tbody></table>`;$('retentionComparison').textContent=retentionPrevious?`Since previous capture: panel entries ${Number(w.entries||0)-Number(retentionPrevious.webPanel?.entries||0)}; retained inventory payloads ${Number(a.loadedPayloads||0)-Number(retentionPrevious.admin?.loadedPayloads||0)}. ${d.note}`:d.note||'';$('retentionState').textContent=`Captured ${fmtAdminTime(d.capturedAt)}`;$('retentionExport').disabled=false;}catch(e){$('retentionState').textContent='Capture failed: '+e.message;toast(e.message,'error');}finally{retentionBusy=false;$('retentionRefresh').disabled=false;}}
function resetInvestigation(){investigationGeneration++;investigationData=null;investigationBusy=false;investigationBlocksBusy=false;$('investigationBody').innerHTML='';$('investigationBlockRows').innerHTML='';$('investigationExport').disabled=true;$('investigationLoad').disabled=false;$('investigationBlocks').disabled=false;$('investigationState').textContent='Details load when requested';}
function decisionMarkup(d){if(!d)return '<p class="small">No current decision telemetry.</p>';return `<p>${esc(d.speedExplanation||'')}</p><p class="small">Confirmed unmounted speed: ${Number(d.confirmedSpeedReports||0)} / ${Number(d.requiredReports||3)} observations in ${Number(d.repeatWindowSeconds||60)}s · Repeat bonus ${Number(d.repeatRiskBonus||0)} / ${Number(d.requiredBonus||50)}. ${esc(d.note||'')}</p><div class="tableWrap"><table><thead><tr><th>Rule</th><th>Action</th><th>State</th></tr></thead><tbody>${(d.rules||[]).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.action)}</td><td>${esc(r.state)}</td></tr>`).join('')||'<tr><td colspan="3">No enabled consequence rules.</td></tr>'}</tbody></table></div>`;}
async function loadPlayerInvestigation(){if(!adminSelectedPlayer||investigationBusy)return;const player=adminSelectedPlayer,generation=investigationGeneration;investigationBusy=true;$('investigationLoad').disabled=true;$('investigationState').textContent='Loading bounded investigation summary…';try{const d=await api('/api/admin/investigation?player='+encodeURIComponent(player));if(generation!==investigationGeneration)return;investigationData=d;const ac=d.antiCheat,p=d.player||{};$('investigationBody').innerHTML=`<div class="grid">${polishMetric('Anti-cheat risk',ac?`${ac.riskScore}/100`:'No current session',ac?.status||'')}${polishMetric('Restrictions',[p.muted?'Muted':'',p.banned?'Banned':'',p.frozen?'Frozen':'',p.jailed?'Jailed':''].filter(Boolean).join(' · ')||'None')}${polishMetric('Inventory snapshots',(d.inventorySnapshots||[]).length,'Header records only')}</div><details open><summary>Why enforcement did or did not act</summary>${decisionMarkup(ac?.decision)}</details><details><summary>Effective role policies</summary>${policyPreviewMarkup(d.role?.effective)}</details><div class="tableWrap"><table><thead><tr><th>Evidence</th><th>Risk points</th><th>Confidence</th><th>Explanation</th></tr></thead><tbody>${(ac?.findings||[]).map(f=>`<tr><td>${esc(f.code)}<br><small>${esc(f.subject)}</small></td><td>${Number(f.riskPoints||0)}</td><td>${esc(f.confidence)}</td><td>${esc(f.why||f.summary)}<details><summary>Evidence</summary><p class="small">${esc(f.evidence)}</p></details></td></tr>`).join('')||'<tr><td colspan="4">No current anti-cheat findings.</td></tr>'}</tbody></table></div><details><summary>Recorded risk changes (${(d.riskHistory||[]).length})</summary><div class="tableWrap"><table><thead><tr><th>Time</th><th>Finding</th><th>Risk before → after</th><th>Consequence</th></tr></thead><tbody>${(d.riskHistory||[]).map(r=>`<tr><td>${esc(fmtAdminTime(r.unixMilliseconds))}</td><td>${esc(r.code)}</td><td>${Number(r.riskBefore||0)} → ${Number(r.riskAfter||0)}</td><td>${esc(r.consequence||'No recorded action')}</td></tr>`).join('')||'<tr><td colspan="4">No recorded risk changes.</td></tr>'}</tbody></table></div></details><p class="small">${esc(d.detailNote)}</p>`;$('investigationState').textContent=`Captured ${fmtAdminTime(d.capturedAt)}`;$('investigationExport').disabled=false;}catch(e){if(generation===investigationGeneration){$('investigationState').textContent='Investigation failed: '+e.message;toast(e.message,'error');}}finally{if(generation===investigationGeneration){investigationBusy=false;$('investigationLoad').disabled=false;}}}
async function loadInvestigationBlocks(){if(!adminSelectedPlayer||investigationBlocksBusy)return;const player=adminSelectedPlayer,generation=investigationGeneration;investigationBlocksBusy=true;$('investigationBlocks').disabled=true;try{const d=await api('/api/admin/block-history?player='+encodeURIComponent(player));if(generation!==investigationGeneration)return;const rows=d.history||[];$('investigationBlockRows').innerHTML=`<table><thead><tr><th>Time</th><th>Action</th><th>Block</th><th>Position</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.timestampUtc)}</td><td>${esc(r.action)}</td><td>${esc(r.blockCode)}</td><td>${Number(r.x)}, ${Number(r.y)}, ${Number(r.z)} · ${esc(r.dimension)}</td></tr>`).join('')||'<tr><td colspan="4">No recorded block history.</td></tr>'}</tbody></table>`;if(investigationData)investigationData.blockHistory=rows;}catch(e){if(generation===investigationGeneration)toast(e.message,'error');}finally{if(generation===investigationGeneration){investigationBlocksBusy=false;$('investigationBlocks').disabled=false;}}}
function invalidateRoleBatch(){rolePolishGeneration++;roleBatchDraft=null;$('roleBatchApply').disabled=true;$('roleBatchState').textContent='Preview required before applying.';}
function bindRolePolish(){invalidateRoleBatch();document.querySelectorAll('[data-role-batch-uid]').forEach(e=>e.onchange=invalidateRoleBatch);document.querySelectorAll('[data-role-effective]').forEach(b=>b.onclick=async()=>{const p=rolePlayersData[Number(b.dataset.roleEffective)],generation=++rolePolishGeneration;if(!p)return;b.disabled=true;try{const d=await api('/api/roles/effective?player='+encodeURIComponent(p.playerUid));if(generation!==rolePolishGeneration)return;$('roleEffectiveResult').hidden=false;$('roleEffectiveResult').innerHTML=`<b>${esc(d.playerName||p.playerName)}</b>${policyPreviewMarkup(d.effective)}`;}catch(e){toast(e.message,'error');}finally{b.disabled=false;}});$('roleBatchPreview').disabled=currentSessionRole==='ReadOnly';}
async function previewRoleDraft(){if(!roleCanWrite()||!$('roleEditor').reportValidity())return;const selected=roleSelected,draft=roleRead(),signature=roleDefinitionSignature(draft),generation=++rolePolishGeneration;$('rolePreview').disabled=true;try{const d=await api('/api/roles/preview',{method:'POST',body:JSON.stringify({action:roleSelected==='__new'?'create':'save',revision:draft.revision,role:draft.row})});if(generation!==rolePolishGeneration||selected!==roleSelected||signature!==roleDefinitionSignature(roleRead()))return;if(!d.success)throw new Error(d.message);$('rolePreviewResult').hidden=false;$('rolePreviewResult').innerHTML=`<p>${Number(d.affectedPlayers||0)} assigned players would use this definition. Nothing has been saved.</p>${policyPreviewMarkup(d.effective)}`;}catch(e){toast(e.message,'error');}finally{roleSync();}}
async function previewRoleBatch(){if(!roleCanWrite())return;const selected=new Set([...document.querySelectorAll('[data-role-batch-uid]:checked')].map(e=>e.dataset.roleBatchUid));if(selected.size<1||selected.size>50){toast('Select 1–50 players.','error');return;}const payload={revision:rolesData.revision,roleCode:$('rolePlayerTarget').value,preview:true,players:rolePlayersData.filter(p=>selected.has(p.playerUid)).map(p=>({playerUid:p.playerUid,expectedRoleCode:p.roleCode}))};const generation=++rolePolishGeneration;$('roleBatchPreview').disabled=true;try{const d=await api('/api/roles/batch',{method:'POST',body:JSON.stringify(payload)});if(generation!==rolePolishGeneration)return;if(!d.success)throw new Error(d.message);const current=[...document.querySelectorAll('[data-role-batch-uid]:checked')].map(e=>e.dataset.roleBatchUid);if(payload.roleCode!==$('rolePlayerTarget').value||current.length!==selected.size||current.some(uid=>!selected.has(uid)))return;roleBatchDraft=payload;$('roleBatchApply').disabled=false;$('roleBatchState').textContent=`Previewed ${payload.players.length} players → ${payload.roleCode}. Direct grants/denials stay in place.`;$('roleEffectiveResult').hidden=false;$('roleEffectiveResult').innerHTML=(d.players||[]).map(p=>`<details><summary>${esc(p.playerName||p.playerUid)}</summary>${policyPreviewMarkup(p.effective)}</details>`).join('');}catch(e){toast(e.message,'error');}finally{$('roleBatchPreview').disabled=!roleCanWrite();}}
async function applyRoleBatch(){if(!roleCanWrite()||!roleBatchDraft)return;const payload=roleBatchDraft;if(!confirm(`Assign ${payload.players.length} previewed players to ${payload.roleCode}?`))return;invalidateRoleBatch();roleBusy=true;roleSync();try{const d=await api('/api/roles/batch',{method:'POST',body:JSON.stringify({...payload,preview:false})});toast(d.message,d.success?'success':'error');}catch(e){toast(e.message,'error');}finally{roleBusy=false;roleSync();await findRolePlayers();}}
$('retentionRefresh').onclick=loadRetentionCounters;$('retentionExport').onclick=()=>{if(retentionData)polishDownload('suite-diagnostics.json',retentionData);};
$('investigationLoad').onclick=loadPlayerInvestigation;$('investigationBlocks').onclick=loadInvestigationBlocks;$('investigationExport').onclick=()=>{if(investigationData)polishDownload('player-investigation.json',investigationData);};
$('rolePreview').onclick=previewRoleDraft;$('roleBatchPreview').onclick=previewRoleBatch;$('roleBatchApply').onclick=applyRoleBatch;$('rolePlayerTarget').addEventListener('change',invalidateRoleBatch);
$('roleEditor').addEventListener('input',()=>{$('rolePreviewResult').hidden=true;});
""";
}
